RTP.Locations = {
	[1] = {id = 1, houseId = 98, owner = "@Zekell", townId = 1, name="Alna District", public = true, description="|u25:0::The|u beating heart of Felms Oad for visitors, traders and residents. "},
	[2] = {id = 2, houseId = 71, owner = "@Zekell", townId = 1, name="Shaln Mora", public = true},
	[3] = {id = 3, houseId = 20, owner = "@Zekell", townId = 1, name="Chamber of Justice", description="|u25:0::The|u Chamber of the local Ordinators of Felms Oad."},
	[4] = {id = 4, houseId = 60, owner = "@Zekell", townId = 1, name="Lan Grotto", public = true, description="|u25:0::The|u old town of Felms Oad, known as the Low or the Lan District. "},
	[5] = {id = 5, houseId = 43, owner = "@Zekell", townId = 1, name="Ruined Indoril Estate"},
	[6] = {id = 6, houseId = 8, owner = "@Zekell", townId = 1, name="Burdened Hall", description="|u25:0::Beneath|u the unfinished Tel taken by House Tavari lies the infirmary. A place of healing, experimentation, alchemy and medicine, run by the healers of House Tavari."},
	[7] = {id = 7, houseId = 46, owner = "@Zekell", townId = 1, name="Market District", public = true, description="|u25:0::The|u market and homestead promenade of Felms Oad. "},
	[8] = {id = 8, houseId = 20, owner = "@Reese1170", townId = 1, name="The Book Repository", description="|u25:0::The|u official library of Felms Oad."},
	[9] = {id = 9, houseId = 55, owner = "@Zekell", townId = 1, name="Sanctuary of Seht", description="|u25:0::A|u hidden sanctuary deep in the Shaln Mora of unknown origin. It is where Sotha Sil's shrine lies, and from where the people of Felms Oad feel he provides blessings from."},
	[10] = {id = 10, houseId = 101, owner = "@Zekell", townId = 1, name="The Ancestor Hall", description="|u25:0::The|u Ancestor Hall is a small but beautifully built location in the giant main stone of Felms Oad. It houses an intentionally unattended to dedication chamber. One where people can commit private rituals and commune with the dead with bother. It also contains the High Gardens. A place of respite and meditation. However you can also sometimes find mer training here as well. Lastly, it holds the Chamber of Preparation, where dead are burnt and placed into urns for mourners. "},
	[11] = {id = 11, houseId = 44, owner = "@random_highjinx", townId = 1, name="The Alchemist's Garden", public = true, description="|u25:0::The|u herb and apothecarial gardens of Felms Oad. "},
	[12] = {id = 12, houseId = 91, owner = "@Daniea", townId = 1, name="Tavari Council Manor"},
	[13] = {id = 13, houseId = 14, owner = "@Zekell", townId = 1, name="Darkden Cavern"},
	[14] = {id = 14, houseId = 71, owner = "@Thelazylizard", townId = 2, name="Rawl'iit Town Center", public = true, description="|u25:0::The|u Town Center of Rawl'iit may look like a bustling settlement, but it was only a few years ago that it was a crumbling ruin of an abandoned adeptorium. The ancient stones of Rawl'iit speak of storied battles, terrible tragedies, triumphs and ignominies, if one but knows how to listen! Underneath the watchful gaze of Jone's Claw Keep a walker arrives at the Caravanserai - an exotic market full of goods from near and far! Beyond that lies the courtyard, where travelers find services such as the tavern and inn, Rainsong Temple, the Sugar Den and the Bank."},
	[15] = {id = 15, houseId = 71, owner = "@TheGhesk", townId = 2, name="The Springlight Woods", public = true, description="|u25:0::Located|u beneath the cliffs of Rawl'iit are the Springlight Woods - a small section of dense tropical rainforests typical of the Tenmar Region. Within the forest are the gates to the old Imperial hamlet of Ruby Row and the entrance to the Ironfang Mines. Travelers beware, for within the deeper, darker sections of the forest lie the abandoned ruins of Old Rawl'iit - scarred and haunted since the Knahaten Flu tore through the area."},
	[16] = {id = 16, houseId = 47, owner = "@Thelazylizard", townId = 2, name="Jone's Claw Keep", public = true, description="|u25:0::Jone's|u Claw Keep is the oldest structure within the Town Center, with the original sections having been constructed shortly after the union of the Sixteen Kingdoms into Two. Shortly after this, the Imperials took claim of it and occupied it for almost a century. Jone's Claw Keep was later returned to the Khajiit adepts of Rain's Fall, who transformed it back into a magnificent Adeptorium. The Keep features a grand dining hall and the Market Council chambers, as well as the bathhouse."},
	[17] = {id = 17, houseId = 68, owner = "@Thelazylizard", townId = 2, name="Wagon's Rest Inn: Small Suite", description="|u25:0::The|u Sleepy Senche Inn features a pair of inn rooms available. For a mere ten gold (10g) a night a weary traveler can rest in a fine suite featuring a comfortable bed with linen changed weekly! (Daily linen changes available for an additional fee!)"},
	[18] = {id = 18, houseId = 22, owner = "@Thelazylizard", townId = 2, name="Wagon's Rest Inn: Deluxe Suite", description="|u25:0::The|u Deluxe Suite of the Sleepy Senche Inn, for those accustomed to a certain level of luxury for long term stays! A living room allows for comfortable private meetings, while the bedroom features a bath and the finest bed, with daily linen changes at no extra cost! Only twenty gold a night!"},
	[19] = {id = 19, houseId = 73, owner = "@Thelazylizard", townId = 2, name="Clan Father's Manor", description="|u25:0::This|u elegant manor is the home of the Caravan Father, Ra'jirroh, and Magistrate of the Town, Mathei. The House dates back to the days of the Potentates, and is one of the finest examples of Pellitine architecture in the region. No expense was spared in its construction, though the long years have left the manor in a state of faded luxury. Despite this the echoes of a once glorious age of gilded wealth still linger, as do the memories of the tragedy that happened here long ago. Visitors are requested to announce their presence before entering."},
	[20] = {id = 20, houseId = 16, owner = "@Thelazylizard", townId = 2, name="Ra'jirroh's Luxury Wagon", description="|u25:0::This|u massive wagon is the pinnacle of Baandari craftsmanship and luxury. It is an abomination that was stitched together from the salvaged remains of rival Baandari merchant's wagons, capable only of traveling on the most well maintained roads and requiring two Senche-Raht to pull. It exists solely to pad the ego of its owner, and make their rival Baandari envious."},
	[21] = {id = 21, houseId = 24, owner = "@Thelazylizard", townId = 2, name="Guard Lodge", public = true, description="|u25:0::Centuries|u ago, the Guard Lodge was the first of the great manor houses that was built within the Riverside district. Over thirty years ago, the manor - and the family that lived there - were burned down almost to the ground to stave off the Flu in the Riverside district. Heavy renovations have left it almost unrecognizable from what it was in those bygone golden years of the area."},
	[22] = {id = 22, houseId = 70, owner = "@Thelazylizard", townId = 2, name="Rainsong Temple", public = true, description="|u25:0::This|u majestic Khajiiti temple is dedicated to the goddess of the Wind, Khenarthi, who ferries Khajiit souls to the Sands beyond the Stars to await the Next Pounce. The temple features a system of vent-like wind catchers on the top of the building that channel the breeze down into the vestibule of the old Temple. In this way even when sheltered from the tropical rainstorms, believers can still feel Khenarthi's breath upon them."},
	[23] = {id = 23, houseId = 49, owner = "@Thelazylizard", townId = 2, name="The Jade Flask", description="|u25:0::Little|u but ruined walls and a tower remain of an old Imperial fort that was later commissioned as a prison. The ruins became a hideout for desperate rogues and bandits after the keep's abandonment, until the ghosts of the prisoners within stirred! After Rawl'iit was re-founded, the ghost infestation was cleared out by Lakjo and the Claws of Baan Dar. The ruins lay unused and forsaken by the local Khajiit until a pair of Argonians moved in and made it their home. Within the old keep they have built the Jade Flask - one of the areas finest alchemy stores!"},
	[24] = {id = 24, houseId = 74, owner = "@Thelazylizard", townId = 2, name="Moonshroud Arena", public = true, description="|u25:0::Beneath|u Rawl'iit are a network of catacombs, caves, aquafers and a great cistern that date as far back as the first foundations of the original structure! This ancient cistern, long disused and forgotten, has been rediscovered and transformed into an underground fighting pit for the town's entertainment!"},
	[25] = {id = 25, houseId = 54, owner = "@Thelazylizard", townId = 2, name="The Ironfang Mines", public = true, description="|u25:0::The|u Ironfang Mines are a set of old mines that were dug into the cliffs during the Imperial occupation of Fort Springmoth, after seams of iron were discovered within. The Imperials mined out several shafts until forced to stop when structural instability was discovered in the fortress walls above. Rumor has it the mines may connect to the sealed catacombs beneath Jone’s Claw Keep!"},
	[26] = {id = 26, houseId = 16, owner = "@Nuketastic2300", townId = 2, name="Ardun-Vylak's Home", description="|u25:0::This|u house was built by a Rim-Man family that fled from Cyrodiil during brutal reign of the Warlord Attrebus. Although it went to ruin during the Knahaten Flu, it has been lovingly restored by its newest owner, Ardun-Vylak."},
	[27] = {id = 27, houseId = 23, owner = "@lavascale133", townId = 2, name="Sandy Bear Smithy", description="|u25:0::This|u blacksmith shop in the Riverside district has recently been renovated and restored by Raliis."},
	[28] = {id = 28, houseId = 26, owner = "@JeffR110", townId = 2, name="The Brass Lion", description="|u25:0::For|u over thirty years the blacksmith in Ruby Row lay cold and crumbling, until Fadorian moved in. In short order the Khajiit Artificer had renovated that old forge with his own artifice, made in the style of the ancient Dwemercraft. Baandari who travel from far north often bring salvaged Dwemer scrap to sell to Fadorian."},
	[29] = {id = 29, houseId = 23, owner = "@Celtic_Cryptid", townId = 2, name="Kaihanna & Ko'ebony's Home", description="|u25:0::Owned|u by Kaihanna and Ko'ebony, this is an example of a number of newer Khajiiti styled structures built in Riverside."},
	[30] = {id = 30, houseId = 22, owner = "@TheGhesk", townId = 2, name="Magistrates Office"},
	[31] = {id = 31, houseId = 64, owner = "@FatherFortune", townId = 3, name="[HH] Ouada Mora", public = true, description="|u25:0::Home|u to House Hladren, a vassal house of Indoril. Built in the shadow of an ancient and abandoned Argonian xanmeer, the town survives on the back of its fishing industry. It's warm, humid, and rains often, but the people are happy, and no one goes hungry."},
	[32] = {id = 32, houseId = 41, owner = "@FatherFortune", townId = 3, name="[BMT] The Undercity", public = true, description="|u25:0::Once|u upon a time, a slaving town that might have grown to rival Tear sat beneath these hills, until an earthquake and mudslides brought it low. Now, just this fragment remains, safe underground. The Baan Maar Tong lives here now, along with escaped slaves and various flavors of ne'er-do-well who seek to escape the attention of the surface-dwellers. "},
	[33] = {id = 33, houseId = 71, owner = "@FatherFortune", townId = 3, name="[HH] Ouada Mora Outskirts", public = true, description="|u25:0::A|u patchwork of humble dwellings and modest homesteads."},
	[34] = {id = 34, houseId = 20, owner = "@FatherFortune", townId = 3, name="[HH] The House of Remedies", public = true, description="|u25:0::Within|u the House of Remedies, skilled menders and alchemists ply their craft to offer healing to the sick and weary."},
	[35] = {id = 35, houseId = 91, owner = "@FatherFortune", townId = 3, name="[HH] The Abbey of Threefold Mercies", public = true, description="|u25:0::Within|u its hallowed halls, the Abbey houses a treasure trove of saintly relics stored there by House Indoril. Pilgrims from far and wide journey to pay homage to these sacred artifacts, seeking divine intervention in their hour of need. It also serves as a sanctuary and orphanage, where children are raised up and cared for by the monks."},
	[36] = {id = 36, houseId = 70, owner = "@FatherFortune", townId = 3, name="[HH] The Hall of Justice", public = true, description="|u25:0::Once|u a Dres manor, but now it serves a more sacred purpose. The Hall of Justice serves as barracks, headquarters, and training grounds for Ouada Mora's Ordinators. In the basement, one can even find housing for the Ordination's... 'guests'."},
	[37] = {id = 37, houseId = 104, owner = "@FatherFortune", townId = 3, name="[HH] The Ghostwood", public = true, description="|u25:0::The|u air here is filled with the fragrance of flowers and the earthy scent of the loam. The wind whispers through the trees and catches whispers of prayer. At the heart of the Ghostwood stands the newly built family tomb of House Hladren. Its presence is an oath sworn that the House will endure. "},
	[38] = {id = 38, houseId = 76, owner = "@FatherFortune", townId = 3, name="[BMT] Boethiah's Run", public = true, description="|u25:0::Descend|u into the depths of Boethiah's Run, and drown in an exquisite sense of dread. The air here is heavy with the scent of sweat and iron. Boethiah's Eye - a vast sinkhole in the center of the main chamber - is eager to witness bloodshed."},
	[39] = {id = 39, houseId = 43, owner = "@DeadKingMars", townId = 3, name="[BMT] Twilight Teahouse", public = true, description="|u25:0::Built|u within the ever growing outskirts of Vivec City, the Twilight Teahouse is a uniquely curated tea ceremony experience for all types of socialites. Owned by renowned Curator Selevis Seren, the Teahouse services those looking for an escape from the hustle and bustle of the city with its colorful gardens and otherworldly beauty."},
}
RTP.Portals = {
	[1] = { -- Alna District
		{id = 0, location = 1, destinations = {2}, x = 100570, y = 20319, z = 101922, cx = 0.580846, cy = 0.747927, portalDescription = "|u25:0::This|u poorly lit cavern leads into the Shaln Mora, the ancient fungal forest of Felms Oad. Go a bit further and it can take you to the civilized Dun Plaza where the market, shops and several estates dwell on the edge of the isle. Know though, that the Shaln Mora is a sacred place. Touched by the Tribunal, Anticipations, ancient tombs and more under a canopy of leaves and fungi. If you run into trouble in the mora, those in town may not be able to rush to your aid. Continue at your own risk if you feel the spiritual reward outweighs it.", icon = "/esoui/art/icons/poi/poi_grove_complete.dds"},
		{id = 1, location = 1, destinations = {3}, x = 94474, y = 10800, z = 84276, cx = 0.43173, cy = 0.316197, portalDescription = "|u25:0::This|u door leads to the Chamber of Justice, a Dark Stone hall built into the island. It houses the offices of the Ordinators of Felms Oad, a small set of cells and a war room. However, this is not the chamber to commit crimes in. Stealing, assault or heresy in the Chamber could lead to being attacked on sight if caught by the local Ordinators. ", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 2, location = 1, destinations = {4}, x = 102210, y = 19675, z = 78269, cx = 0.621061, cy = 0.169292, portalDescription = "|u25:0::This|u path leads down to The Grotto of Felms Oad. Otherwise known as The Village. It keeps the ships of House Tavari guarded at a port, serves as a home to some citizens in shacks and cavern homes, and also houses the well known Tendal's Tradehouse and Hall of Laborers and Artisans.", icon = "/esoui/art/icons/poi/poi_cave_complete.dds"},
		{id = 3, location = 1, destinations = {6}, x = 94090, y = 11250, z = 79769, cx = 0.422333, cy = 0.205915, radius = 5, portalDescription = "|u25:0::This|u door leads down to the dark depths of the tower, home of the Order of the Burdened. A place to purchase apothecarial and alchemical goods, as well as seek out healing for sickness or injury. But do be warned, those who lurk in this hall just to lurk may be asked to leave. That is unless you are of the Burdened. You can often find it's members working below under Ayem's healing hands. ", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 4, location = 1, destinations = {10}, x = 99451, y = 21295, z = 86867, cx = 0.553483, cy = 0.37963, portalDescription = "|u25:0::The|u Ancestor Hall. This elegant building is built into the stone of Felms Oad, and serves as place to connect and communicate with the dead, as per ancient Dunmeri tradition. It also houses a fine overlook of the tower's port for those wanting privacy and relaxation high in the cliffs of the isle. ", icon = "/esoui/art/icons/poi/poi_crypt_complete.dds"},
		{id = 5, location = 1, destinations = {7}, x = 93277, y = 19378, z = 88293, cx = 0.402432, cy = 0.414456, portalDescription = "|u25:0::This|u gate leads out of the Alna District and to the Market District. A lime-and-volcanic-stone pit of shops and services. Including a promenade and other fascinating locales. It is often bustling with life as merchants shout out to potential customers and sailors roam in to unload goods from across Morrowind. You can also find some cave Manors here, held by distinct mer of the region. ", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_open.dds"},
		{id = 6, location = 1, destinations = {12}, x = 104591, y = 20060, z = 90514, cx = 0.679243, cy = 0.468767, portalDescription = "|u25:0::The|u stronghold door before you leads to the Tavari Council Manor. A place of summits, private conferences and dinners, as well as audience with members of the House Council.", icon = "/esoui/art/icons/poi/poi_estate_complete.dds"},
	},
	[2] = { -- Shaln Mora
		{id = 0, location = 2, destinations = {1}, x = 59165, y = 29521, z = 54675, cx = 0.32576, cy = 0.313665, portalDescription = "|u25:0::This|u cavern is poorly lit but it will get you back to the Alna District, the capital district of Felms Oad.", icon = "/esoui/art/icons/mapkey/mapkey_soloinstance.dds"},
		{id = 1, location = 2, destinations = {5}, x = 67428, y = 30470, z = 58431, cx = 0.508826, cy = 0.396862, portalDescription = "|u25:0::This|u door leads to a long abandoned and ruined Indoril Estate. Rumors say Argonian slaves broke free and killed the family who once lived here. Now it lies empty as a ruin and reminder. Few care to revisit the site. ", icon = "/esoui/art/icons/poi/poi_estate_complete.dds"},
		{id = 2, location = 2, destinations = {9}, x = 69483, y = 28896, z = 52544, cx = 0.55443, cy = 0.266427, portalDescription = "|u25:0::This|u strange lift lowers you into the hidden Sanctuary of Sotha Sil, protected by the Temple and made of dark Velothi stone and metallic trimmings. A place where the locals feel and know he provides his blessings from. Down below and with mystery is how the Wizard helps the Mother and Warrior-Poet guide the area and protect the faithful. It is said, when one stands before his shrine, the comforting, quiet rhythm of gears turn in hearts and minds.", icon = "/esoui/art/icons/mapkey/mapkey_temple.dds"},
		{id = 3, location = 2, destinations = {13}, x = 66508, y = 29135, z = 62125, cx = 0.488558, cy = 0.478751, portalDescription = "|u25:0::A|u strange cavern tucked in the Shaln Mora of the isle. The air inside is stale and cold. It's clear to those with a touch of magicka, or even common sense that something is not quite right inside.", icon = "/esoui/art/icons/poi/poi_cave_complete.dds"},
	},
	[3] = { -- Chamber of Justice
		{id = 0, location = 3, destinations = {1}, x = 52856, y = 9536, z = 45852, cx = 0.172344, cy = 0.558009, portalDescription = "|u25:0::This|u door leads back into the chapel of the Abbey of Saint Felms the Bold.", icon = "/esoui/art/icons/mapkey/mapkey_avatown.dds"},
	},
	[4] = { -- Lan Grotto
		{id = 0, location = 4, destinations = {1}, x = 86004, y = 10231, z = 72996, cx = 0.691821, cy = 0.425194, portalDescription = "|u25:0::This|u passageway leads back to the Alna District. The center and heart of Felms Oad where you can find the Tel, Abbey of Saint Felms, Excise Office and more. ", icon = "/esoui/art/icons/mapkey/mapkey_avatown.dds"},
		{id = 1, location = 4, destinations = {2}, x = 92479, y = 10031, z = 82245, cx = 0.823591, cy = 0.613407, portalDescription = "|u25:0::This|u dark cavern leads up to connect with another, guiding you to the Shaln Mora, the spiritual place of Felms Oad aside from The Abbey of Saint Felms. While the Shaln Mora is not regularly patrolled, within the forest you can find shrines to anticipations and God-Kings, tombs and many other secrets. It also is where one walks the Pilgrimage of Brothers Beraul. ", icon = "/esoui/art/icons/poi/poi_grove_complete.dds"},
	},
	[5] = { -- Ruined Indoril Estate
		{id = 0, location = 5, destinations = {2}, x = 50434, y = 12466, z = 51930, cx = 0.445943, cy = 0.762682, portalDescription = "|u25:0::The|u door back into the Shaln Mora and out of the old walled estate.", icon = "/esoui/art/icons/poi/poi_grove_complete.dds"},
	},
	[6] = { -- Burdened Hall
		{id = 0, location = 6, destinations = {1}, x = 24184, y = 20008, z = 22665, cx = 0.652075, cy = 0.582595, portalDescription = "|u25:0::This|u door leads back up to the main floor of the lighthouse.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[7] = { -- Market District
		{id = 0, location = 7, destinations = {8}, x = 55622, y = 19630, z = 100202, cx = 0.753964, cy = 0.221184, portalDescription = "|u25:0::In|u the market district, the Book Repository of Felms Oad is run by Aryni Sadris of House Tavari. It contains a public section and a well guarded restricted section on the lower level. If you intend to take any tomes home, do know the tomekeepers are known for thorough check out processes and paperwork.", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 1, location = 7, destinations = {1,2}, x = 56982, y = 19400, z = 101157, cx = 0.759404, cy = 0.225004, portalDescription = "|u25:0::This|u door leads back through to the Alna District of Felms Oad. This is the heart of the isle, where you can find the tower, a cornerclub, the Abbey of Saint Felms and more. However, it can also take you back into the ancient fungal forest if you decide to walk through the beaches.", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_open.dds"},
		{id = 2, location = 7, destinations = {11}, x = 55097, y = 19540, z = 94418, cx = 0.751864, cy = 0.198048, portalDescription = "|u25:0::This|u gate leads to the Alchemist's Garden venue, which is managed by the the Order of the Burdened. It is a small building and courtyard for alchemists and apothecaries looking to collect or harvest goods for their work. Those looking to use the service will be asked to pay a fee upon departure should they leave having claimed goods or services. ", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_open.dds"},
	},
	[8] = { -- The Book Repository
		{id = 0, location = 8, destinations = {7}, x = 52871, y = 9536, z = 45863, cx = 0.172381, cy = 0.558037, portalDescription = "|u25:0::The|u door out of the Book Repository and back into the Market District. ", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[9] = { -- Sanctuary of Seht
		{id = 0, location = 9, destinations = {2}, x = 55920, y = 50302, z = 105493, cx = 0.223041, cy = 0.421939, portalDescription = "|u25:0::This|u odd lift takes you back up into the Shaln Mora district of Felms Oad.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[10] = { -- The Ancestor Hall
		{id = 0, location = 10, destinations = {1}, x = 79092, y = 4428, z = 54105, cx = 0.69096, cy = 0.213086, portalDescription = "|u25:0::This|u door leads back to the the Alna District of Felms Oad, just outside the Abbey of Saint Felms the Bold.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[11] = { -- The Alchemist's Garden
		{id = 0, location = 11, destinations = {7}, x = 39508, y = 12327, z = 82264, cx = 0.199334, cy = 0.274395, portalDescription = "|u25:0::This|u leads back into the Market District of Felms Oad.", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_open.dds"},
