	[12] = { -- Tavari Council Manor
		{id = 0, location = 12, destinations = {1}, x = 80231, y = 52492, z = 61963, cx = 0.564293, cy = 0.183847, portalDescription = "|u25:0::This|u door leads back to the Alna District of Felms Oad. ", icon = "/esoui/art/icons/mapkey/mapkey_avatown.dds"},
	},
	[13] = { -- Darkden Cavern
		{id = 0, location = 13, destinations = {2}, x = 44336, y = 11509, z = 52403, cx = 0.391798, cy = 0.731796, portalDescription = "|u25:0::This|u leads back out into the sacred fungal woodlands of Felms Oad. ", icon = "/esoui/art/icons/poi/poi_cave_complete.dds"},
	},
	[14] = { -- Rawl'iit Town Center
		{id = 0, location = 14, destinations = {15}, x = 67362, y = 29099, z = 62388, cx = 0.507355, cy = 0.484472, radius = 200, portalDescription = "|u25:0::Past|u these gates is a terrifying road carved into the surface of the cliffs themselves. This narrow road navigates the cliffs down into the jungle basin of the Springlight Woods. Travelers should exercise extreme caution on the roads - one wrong step can send a careless Walker down a hundred foot drop into the jungle basin below! ", icon = "/esoui/art/icons/poi/poi_grove_complete.dds"},
		{id = 1, location = 14, destinations = {30}, x = 66504, y = 29329, z = 61140, cx = 0.488395, cy = 0.456849, portalDescription = "|u25:0::Beyond|u these doors lie the Old Barracks. The lobby of the Magistrate's office is the first room that a walker will enter upon stepping through the door.", icon = "/esoui/art/icons/servicemappins/servicepin_museum.dds"},
		{id = 2, location = 14, destinations = {16}, x = 65104, y = 29226, z = 63043, cx = 0.457339, cy = 0.499019, portalDescription = "|u25:0::These|u doors lead into the atrium of Jone's Claw Keep - the oldest and tallest structure in Rawl'iit. On the left-hand door is carved with a scene of an ancient Khajiiti adept facing off against two other Khajiit - a Senche-Raht and a Cathay-Raht. He stands between those fearsome figures and cowering innocents. On the right hand door, the grand adept stands triumphantly over the bodies of the slain Senche-Raht and Cathay-Raht, while others celebrate joyously. Inscribed upon it is a sentence in Ta'agra: \"Do-Zakarr saves Rawl'iit from the Thundermaw Raiders.\"", icon = "/esoui/art/icons/mapkey/mapkey_outpost.dds"},
		{id = 3, location = 14, destinations = {17,18}, x = 63755, y = 29226, z = 66009, cx = 0.427427, cy = 0.564727, nameOverride = "Wagon's Rest Inn", portalDescription = "|u25:0::The|u Wagon's Rest Inn has rooms available for travelers looking to get a good night's sleep in a bed! A pair of suites are offered for rent - a small inn room for shorter stays, and a deluxe room for extended visits!", icon = "/esoui/art/icons/mapkey/mapkey_inn.dds"},
		{id = 4, location = 14, destinations = {19,21,27,29}, x = 66538, y = 29228, z = 71923, cx = 0.489212, cy = 0.695816, nameOverride = "Riverside District", portalDescription = "|u25:0::These|u are the gates to the Riverside District, where the majority of the town's residences are found. This district is built along one of the major arteries of the river that separates Grahtwood and Pellitine. Stately Khajiit manors and farmsteads in various states of restoration or decay line the roads, which are sometimes graced by traders bringing goods upriver. At the edge of the district lie the farms that produce the region's Springlight Silk.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
		{id = 5, location = 14, destinations = {22}, x = 72679, y = 29070, z = 70117, cx = 0.625204, cy = 0.65577, portalDescription = "|u25:0::Gold|u inlaid doors lie before you, carved with a most intricate scene. Khajiit of various furstocks climb upon the stars, their eyes drawn upwards towards the pair of moons at the top of the arched doors. They follow after a sphynx-like female - a figure most Khajiit would recognize as Khenarthi. It is a scene of her leading the souls of True Cats to the Sands Beyond the Stars, indicating this building to be a temple dedicated in Her name.", icon = "/esoui/art/icons/mapkey/mapkey_temple.dds"},
		{id = 6, location = 14, destinations = {24}, x = 70761, y = 28988, z = 69243, cx = 0.582707, cy = 0.636319, portalDescription = "|u25:0::Beyond|u this door lies a set of stairs leading down underneath Jone's Claw Keep. The doors themselves once had carvings upon them like many in Rawl'iit, but these have long since become warn down with time and weathering - to the point that the figures upon them have become mostly imperceptible. The sentence 'Rajhin steals a stupid carving' has been crudely etched on the right hand door.", icon = "/esoui/art/icons/mapkey/mapkey_battle.dds"},
		{id = 7, location = 14, destinations = {16}, x = 68428, y = 29905, z = 68676, cx = 0.531056, cy = 0.623733, portalDescription = "|u25:0::Upon|u these double doors are carved elaborate scenes from Rawl'iit's history. On the left hand door the adepts are seen battling against Men in segmented armor, wielding tall shields and broad yet short swords. The Khajiit adepts stand upon a great gatehouse, shooting arrows at the invading Men. The scene shifts past that gatehouse onto the right hand door, where on the other side the Men march beneath a burning Khajiiti tower.", icon = "/RoleplayTownPortals/icons/doorbig.dds"},
	},
	[15] = { -- The Springlight Woods
		{id = 0, location = 15, destinations = {14}, x = 59263, y = 29521, z = 54738, cx = 0.328048, cy = 0.314972, portalDescription = "|u25:0::Beyond|u these gates lie the narrow cliff road leading up to the Town Center. It is a hard journey going up that can wear out all but the most fit of Khajiit. It is made all the more difficult by the frequent rain that cascades down the cliffs, rendering the stones slippery. Carts are forced to perilously draw close to the edge of the road to pass one another - and it is during this time, as a passenger glances out the window, that they see the terrifying drop into the mist shrouded Springlight Woods awaiting below should they fall.", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_closed.dds"},
		{id = 1, location = 15, destinations = {26,23,28}, x = 66728, y = 29203, z = 59699, cx = 0.493298, cy = 0.424975, nameOverride = "Ruby Row", portalDescription = "|u25:0::Beyond|u these gates is the hamlet of Ruby Row - a small cluster of Akaviri inspired Imperial houses and shops. It is bordered on the south by the swamp of Brazollus's Folly, and by the Izora-ko river to the east. Upon entering through the gates a walker finds the hamlet's outskirts, which straddle either side of the road. Caravans travel past the gates between Rain's Fall and Chasegrove, which are constructed from Corinthe's white stone.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
		{id = 2, location = 15, destinations = {25}, x = 68832, y = 28999, z = 77536, cx = 0.540046, cy = 0.820039, portalDescription = "|u25:0::A|u dark and foreboding entrance yawns before you. From it cool wind occasionally wafts up from deeper tunnels, sharply contrasting the humid jungle air around you. These are the Ironfang Mines, from which the town gathers iron. Deeper within the mines, dormant Aeonstone can be found, as well as breaches into the ancient catacombs where terrible things were once imprisoned.", icon = "/esoui/art/icons/poi/poi_cave_complete.dds"},
		{id = 3, location = 15, destinations = {}, x = 66170, y = 29226, z = 71043, cx = 0.48104, cy = 0.676201, nameOverride = "The Deep Woods", portalDescription = "|u25:0::Beyond|u this gateway lie the roads leading deeper into the Springlight Woods. The territories of Rawl'iit extend for a few miles to the south before the river and karsts that mark the border between the lands around Torval and Rawl'iit. Other paths beyond will lead travelers across the border of Valenwood.", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_open.dds"},
	},
	[16] = { -- Jone's Claw Keep
		{id = 0, location = 16, destinations = {14}, x = 82501, y = 37022, z = 86968, cx = 0.56618, cy = 0.542338, radius = 20, portalDescription = "|u25:0::These|u are the side doors of the Keep which exit out to the main street of the Town Square. It is carved with a scene of great battle - of two Khajiit fighting against a dark spirit, who's visage has been vandalized and defaced with a chisel. The moons of Jone and Jode hover behind the two Khajiit women's heads like halo's. There is a sentence in Ta'agra carved over the top: \"Zabarra and Jira-ko banish the False Ra.\"", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 1, location = 16, destinations = {}, x = 85327, y = 37913, z = 85377, cx = 0.566835, cy = 0.541972, nameOverride = "The Tower", portalDescription = "|u25:0::Beyond|u this door lie a series of stairs that lead up into the Tower. It is said that some nights one can hear the voices of Khajiit speaking within there, even though there is a heavy lock on the door and a sign reading \"No Access!\"", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 2, location = 16, destinations = {14}, x = 84262, y = 38014, z = 89890, cx = 0.566587, cy = 0.543015, portalDescription = "|u25:0::Upon|u the large doors of this hall are carved an elaborate scene of Khajiit gathered around a great feasting table. A feminine Tojay-Raht stands up at the head of the table with a short, curved blade raised in the air as if in triumph. Behind her are two radiant moons that envelop her head like a halo, shining their light upon those gathered.", icon = "/RoleplayTownPortals/icons/doorbig.dds"},
		{id = 3, location = 16, destinations = {14}, x = 83067, y = 36923, z = 83400, cx = 0.566311, cy = 0.541512, portalDescription = "|u25:0::This|u door leads to the Market Courtyard of Rawl'iit's town center. Beyond the heavy gates is the entryway, with an elegantly carved set of double doors leading outside. Engraved on the door panels are images of that Khajiit called Do'Zakarr featured on the other side of the door, training new adepts. A tall male Cathay-Raht is among them, as well as two Khajiit women - one a Tojay-Raht, the other a Cathay.", icon = "/RoleplayTownPortals/icons/townsquare.dds"},
		{id = 4, location = 16, destinations = {}, x = 82202, y = 37024, z = 85858, cx = 0.566111, cy = 0.542081, nameOverride = "West Balcony", portalDescription = "|u25:0::These|u barred doors lead to the western balcony of the Atrium. The panels of the doors are intricately carved with scenes of Khajiit adepts battling one another. One group of almost skeletal monks on the left hand door is led by a dark khajiit spirit who's visage has been defaced. The right hand door features two Khajiit women with their heads wreathed in moon-like halos leading a smaller group of True Cats against the spirits.", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 5, location = 16, destinations = {}, x = 83868, y = 37024, z = 85837, cx = 0.566497, cy = 0.542077, nameOverride = "East Balcony", portalDescription = "|u25:0::These|u double doors lead to a set of stairs that ascend to the Eastern Balcony. Carved on the left hand door was the Khajiit that had saved the innocents of Old Rawl'iit from the Thundermaw Raiders kneeling before an altar, with an image of Khenarthi emerging from sugar-smoke above him. Yet behind him lurks another Khajiit with a dagger. On the right hand door, the Adept lies dead - and Khenarthi turns away in shame as the murderer claims his mantle.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[17] = { -- Wagon's Rest Inn: Small Suite
		{id = 0, location = 17, destinations = {14,18}, x = 21458, y = 10134, z = 27589, cx = 0.270878, cy = 0.633784, nameOverride = "Inn Room Doors", portalDescription = "|u25:0::The|u hustle and bustle of the Wagon's Rest Inn can be heard beyond these doors. (To be fair, they can also be heard through the thinner walls of this cheaper room!) Beyond them a walker will find the small lobby of the Inn, with its carved doors surrounded by colored glass that lead out into the main street of the Town Center.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[18] = { -- Wagon's Rest Inn: Deluxe Suite
		{id = 0, location = 18, destinations = {14,17}, x = 33783, y = 20077, z = 26068, cx = 0.406325, cy = 0.617475, nameOverride = "Inn Room Doors", portalDescription = "|u25:0::The|u hustle and bustle of the Wagon's Rest Inn can be heard beyond these doors. Beyond them a walker will find a set of stairs leading down to the small lobby of the Inn, with its carved doors surrounded by colored glass that lead out into the main street of the Town Center.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[19] = { -- Clan Father's Manor
		{id = 0, location = 19, destinations = {20}, x = 49497, y = 15013, z = 60919, cx = 0.771343, cy = 0.61916, portalDescription = "|u25:0::This|u gate leads to the manor's private stables, where the Caravan Master's luxury wagon is stored. This massive abomination is forged from the remains of rival Baandari's wagons, is too large to travel on most roads, and requires two senche-raht to pull it (who are barely capable of this feat). It exists to spite those unfortunate enough to have to share the road with it.", icon = "/esoui/art/icons/mapkey/mapkey_caravan.dds"},
		{id = 1, location = 19, destinations = {14,21,27,29}, x = 47820, y = 15226, z = 63102, cx = 0.747085, cy = 0.650736, nameOverride = "Riverside Gates", portalDescription = "|u25:0::Beyond|u this gate lies the Riverside District. Ra'jirroh's walled manor looms tall over most of this district, which hosts most of the residences of Rawl'iit as well as some specialized shops. The northern end of the district is bordered by the wall dividing Riverside and the Town Center, while at the far southern end one can find silk and spice farms.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
	},
	[20] = { -- Ra'jirroh's Luxury Wagon
		{id = 0, location = 20, destinations = {14}, x = 19635, y = 20026, z = 29025, cx = 0.312554, cy = 0.789918, portalDescription = "|u25:0::All|u roads eventually lead home...", icon = "/esoui/art/icons/mapkey/mapkey_caravan.dds"},
	},
	[21] = { -- Guard Lodge
		{id = 0, location = 21, destinations = {14,19,27,29}, x = 33938, y = 19831, z = 53393, cx = 0.773768, cy = 0.281806, nameOverride = "Gate to Riverside", portalDescription = "|u25:0::Beyond|u this gate lies the Riverside District. Ra'jirroh's walled manor looms tall over most of this district, which hosts most of the residences of Rawl'iit as well as some specialized shops. The northern end of the district is bordered by the wall dividing Riverside and the Town Center, while at the far southern end one can find silk and spice farms.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
	},
	[22] = { -- Rainsong Temple
		{id = 0, location = 22, destinations = {14}, x = 105478, y = 10357, z = 91599, cx = 0.453546, cy = 0.228836, portalDescription = "|u25:0::As|u these double doors swing open a swift humid breeze pours through the opening into Khenarthi's Temple. Immediately outside lay the temple's courtyard at the very edge of the Town Center.", icon = "/RoleplayTownPortals/icons/doorbig.dds"},
	},
	[23] = { -- The Jade Flask
		{id = 0, location = 23, destinations = {15,26,28}, x = 60802, y = 10122, z = 46883, cx = 0.702887, cy = 0.436447, nameOverride = "Gate to Ruby Row", portalDescription = "|u25:0::This|u gate leads to Ruby Row, and from there to the Springlight Woods. The Jade Flask is located at the far southern edges of this old district, the tilted tower looming over the low, silty marshes that form naturally at the bottom of the Springlight Basin.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[24] = { -- Moonshroud Arena
		{id = 0, location = 24, destinations = {14}, x = 39672, y = 3512, z = 55942, cx = 0.267685, cy = 0.258773, portalDescription = "|u25:0::Beyond|u these doors lie a series of stairs leading up to the Temple Courtyard of the Town Center.", icon = "/RoleplayTownPortals/icons/doorbig.dds"},
	},
	[25] = { -- The Ironfang Mines
		{id = 0, location = 25, destinations = {15}, x = 55412, y = 61493, z = 82550, cx = 0.904314, cy = 0.413554, portalDescription = "|u25:0::The|u humid air of the rain-forest blows through this yawning exit from the mines. Despite this, there seems to be a chill to the caverns behind you that cannot be pushed back even by the tropical air coming in.", icon = "/esoui/art/icons/mapkey/mapkey_artifactgate_closed.dds"},
	},
	[26] = { -- Ardun-Vylak's Home
		{id = 0, location = 26, destinations = {28,23,15}, x = 19650, y = 20026, z = 29035, cx = 0.312595, cy = 0.789945, nameOverride = "Ardun's Door", portalDescription = "|u25:0::These|u gates lead out to a road that curves to the left and the right. A single stream follows the side of the road, over which Akaviri styled foot-bridges with exaggerated curves and snake motifs cross. Ardun-Vylak's home is the finest preserved example of the houses built by Rim-Men refugees of Attrebus's purges. A cherry tree planted for Ardun's ancestors stands at the stream's edge. ", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
	[27] = { -- Sandy Bear Smithy
		{id = 0, location = 27, destinations = {21,19,14,29}, x = 22815, y = 14001, z = 25709, cx = 0.438822, cy = 0.499611, nameOverride = "Riverside Gate", portalDescription = "|u25:0::The|u Riverside district lies beyond this gate. Ra'jirroh's walled manor looms tall over most of this district, which hosts most of the residences of Rawl'iit as well as some specialized shops. The northern end of the district is bordered by the wall dividing Riverside and the Town Center, while at the far southern end one can find silk and spice farms.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
	},
	[28] = { -- The Brass Lion
		{id = 0, location = 28, destinations = {26,23,15}, x = 44157, y = 34600, z = 56783, cx = 0.887286, cy = 0.625311, nameOverride = "Gates to Ruby Row", portalDescription = "|u25:0::These|u gates lead out to a road that curves uphill to the right. A single stream follows the side of the road, over which Akaviri styled foot-bridges with exaggerated curves and snake motifs cross. The Brass Lion is the largest building in Ruby Row, and is located at the lowest section of the narrow valley. The water of the stream is used to cool Fad's forges.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
	},
	[29] = { -- Kaihanna & Ko'ebony's Home
		{id = 0, location = 29, destinations = {14,19,21,27}, x = 22776, y = 14001, z = 25804, cx = 0.438705, cy = 0.499898, nameOverride = "Gate to Riverside", portalDescription = "|u25:0::Beyond|u this gate lies the Riverside District. Ra'jirroh's walled manor looms tall over most of this district, which hosts most of the residences of Rawl'iit as well as some specialized shops. The northern end of the district is bordered by the wall dividing Riverside and the Town Center, while at the far southern end one can find silk and spice farms.", icon = "/RoleplayTownPortals/icons/signpost.dds"},
	},
	[30] = { -- Magistrates Office
		{id = 0, location = 30, destinations = {14}, x = 33811, y = 20077, z = 26185, cx = 0.406462, cy = 0.618012, portalDescription = "|u25:0::These|u doors will lead you outside of the Old Barracks and into the Market Courtyard. Even now, the smell of the markets exotic spices and foods tease the nose through the cracks of the doors.", icon = "/RoleplayTownPortals/icons/door.dds"},
		{id = 1, location = 30, destinations = {}, x = 33188, y = 20100, z = 25971, cx = 0.4036, cy = 0.617025, nameOverride = "Old Barracks", portalDescription = "|u25:0::Beyond|u these doors are the deeper parts of the Old Barracks. There is a short hallway beyond this door that leads to two destinations. A heavy set of doors on the right will take walkers to Rawl'iit's jail, while walking straight ahead will take them to the armory.", icon = "/RoleplayTownPortals/icons/door.dds"},
	},
